using UnityEngine;using UnityEditor;using System.Linq;using System.Text;
public static class ProbeRoad{public static string Main(){var sb=new StringBuilder();var terrain=Terrain.activeTerrains[0];foreach(var m in Object.FindObjectsByType<MotorollerController>(FindObjectsSortMode.None)){using var so=new SerializedObject(m);var c=so.FindProperty("collisionCenter").vector3Value;var e=Vector3.Scale(so.FindProperty("collisionHalfExtents").vector3Value,m.transform.lossyScale);int bad=0;for(float z=78;z<=108;z+=3)for(float x=36;x<=66;x+=3){var p=new Vector3(x,0,z);p.y=terrain.SampleHeight(p)+terrain.transform.position.y+.02f;var hits=Physics.BoxCastAll(p+Vector3.Scale(c,m.transform.lossyScale),e,Vector3.forward,Quaternion.identity,.225f,~0,QueryTriggerInteraction.Ignore);var hit=hits.FirstOrDefault(h=>!h.transform.IsChildOf(m.transform)&&h.normal.y<=.65f);if(hit.collider!=null){bad++;if(bad<=12)sb.AppendLine(m.name+" at "+p+" hits "+hit.collider.name+" "+hit.collider.GetType().Name+" distance="+hit.distance+" normal="+hit.normal);}}sb.AppendLine("Blocked samples="+bad);}
var colliders=Physics.OverlapBox(new Vector3(51,11,93),new Vector3(18,9,18));sb.AppendLine(string.Join("\n",colliders.Where(c=>!(c is TerrainCollider)).Select(c=>c.name+" "+c.GetType().Name+" bounds="+c.bounds).Take(55)));return sb.ToString();}}
